// Three realistic feedback samples exercising sentiment, churn risk and the escalation router.
return [
  { json: { Channel: 'Review', Customer: 'Ada Lovelace',
    Feedback: 'Honestly the onboarding was the best I have seen — your team replied in minutes and the product just works. Renewing for sure.' } },
  { json: { Channel: 'Support ticket', Customer: 'BigCorp Ltd',
    Feedback: 'This is the third outage this month. We are a paying customer and we have lost real money. If this happens again we are cancelling and moving to a competitor.' } },
  { json: { Channel: 'Survey', Customer: '',
    Feedback: 'Quick question — does the Pro plan include API access, or is that a paid add-on? Just trying to plan our integration.' } }
];

// Read the form submission (or the TEST sample) and build the AI input. Iterates all items.
const MAX = 4000;
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  let text = String(j.Feedback || j.feedback || '').trim();
  if (text.length > MAX) text = text.slice(0, MAX) + ' …[truncated]';
  const channel = String(j.Channel || j.channel || 'Review').trim();
  const customer = String(j.Customer || j.customer || '').trim();
  out.push({ json: {
    text, channel, customer,
    sourcePreview: text.slice(0, 120),
    analyzedAt: $now.toISO(),
    aiInput: `CHANNEL: ${channel}\nCUSTOMER: ${customer || '(anonymous)'}\n\nFEEDBACK:\n${text}`
  }});
}
return out;

// Honest guardrail: coerce to allowed values, flag malformation, compute the escalation decision here
// (so routing is deterministic, not left to the model). Pairs AI output with its source by position.
const SENT = new Set(['positive','neutral','negative']);
const PRIS = new Set(['high','normal','low']);
const preps = $('Prepare feedback').all();
const items = $input.all();
const asArr = v => Array.isArray(v) ? v : (v ? String(v).split(/[,;\n]/).filter(Boolean) : []);
const out = [];
for (let i = 0; i < items.length; i++) {
  const src = items[i].json;
  const ai = (src && typeof src.output === 'object' && src.output) ? src.output : src;
  const prep = (preps[i] || preps[0] || { json: {} }).json;
  let sentiment = String(ai.sentiment || '').toLowerCase().trim();
  let priority  = String(ai.priority  || '').toLowerCase().trim();
  let churn = ai.churn_risk === true || String(ai.churn_risk).toLowerCase() === 'true';
  let themes = asArr(ai.themes).map(s => String(s).trim()).filter(Boolean);
  let summary = String(ai.summary || '').trim();
  let reply = String(ai.suggested_reply || '').trim();
  let lang = String(ai.detected_language || '').trim();
  let malformed = false;
  if (!SENT.has(sentiment)) { sentiment = 'neutral'; malformed = true; }
  if (!PRIS.has(priority)) { priority = 'normal'; }
  if (!summary) { summary = '(no summary produced)'; malformed = true; }
  // Deterministic escalation rule — not the model's call:
  const escalate = (churn || (sentiment === 'negative' && priority === 'high')) ? 'yes' : 'no';
  out.push({ json: {
    analyzedAt: prep.analyzedAt, customer: prep.customer, channel: prep.channel,
    sourcePreview: prep.sourcePreview, detectedLanguage: lang,
    sentiment, priority, churnRisk: churn,
    themes: themes.join(', '), summary, suggestedReply: reply,
    escalate, needsReview: malformed,
    analyzerVersion: 'perly-feedback-analyzer-v1.0'
  }});
}
return out;

// Tolerant assertions: invariants, not exact strings.
const SENT=new Set(['positive','neutral','negative']); const PRIS=new Set(['high','normal','low']);
const rows=$input.all().map(i=>i.json); const problems=[];
for(const r of rows){
  if(!SENT.has(r.sentiment)) problems.push(`bad sentiment: ${r.sentiment}`);
  if(!PRIS.has(r.priority)) problems.push(`bad priority: ${r.priority}`);
  if(!r.themes) problems.push('no themes');
  if(!r.summary) problems.push('no summary');
  if(!['yes','no'].includes(r.escalate)) problems.push(`bad escalate flag: ${r.escalate}`);
}
const angry = rows.find(r => /outage|cancelling|competitor/i.test(r.sourcePreview) || /BigCorp/i.test(r.customer));
if(!angry) problems.push('churn sample not found');
else { if(angry.escalate!=='yes') problems.push('churn/angry feedback was NOT escalated');
       if(angry.sentiment!=='negative') problems.push('angry feedback not marked negative'); }
const happy = rows.find(r => /onboarding|renewing/i.test(r.sourcePreview));
if(happy && happy.escalate!=='no') problems.push('happy feedback was wrongly escalated');
const esc = rows.filter(r=>r.escalate==='yes').length;
// Un test che fallisce deve FALLIRE, non restituire un oggetto triste che nessuno
// legge. Senza questa riga l'esecuzione resta verde e il pannello di n8n dice che
// è andato tutto bene: esattamente il guasto silenzioso contro cui esiste il test.
if (problems.length) {
  throw new Error(`TEST FAILED (${problems.length}): ` + problems.join(' | '));
}
return [{json:{result:problems.length?'FAILED':'PASSED',checked:rows.length,escalated:esc,problems,
  triage:rows.map(r=>`${(r.customer||'anon').slice(0,10)} -> ${r.sentiment}/${r.priority}/churn:${r.churnRisk}/esc:${r.escalate}`)}}];
